                                                                                                                                                                                                                 
  CREATE TABLE "FMP_SYS_CONFIG"                                                                                                                                                                        
   (	"SYS_CONFIG_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CONFIG_TYPE" NUMBER(10,0),                                                                                                                                                                                     
	"CONFIG_NAME" VARCHAR2(50),                                                                                                                                                                                     
	"CONFIG_CODE" VARCHAR2(255),                                                                                                                                                                                    
	"IS_ENABLE" NUMBER(1,0) DEFAULT 1,                                                                                                                                                                              
	"REMARK" VARCHAR2(255),                                                                                                                                                                                         
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0,                                                                                                                                                                               
	"TENANT_ID" NUMBER(20,0) DEFAULT 3,                                                                                                                                                                             
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                      
	"CREATION_DATE" DATE DEFAULT sysdate,                                                                                                                                                                           
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                      
	"UPDATE_DATE" DATE DEFAULT sysdate,                                                                                                                                                                             
	"SORT_NUM" NUMBER(20,0) DEFAULT 1,                                                                                                                                                                              
	 PRIMARY KEY ("SYS_CONFIG_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                            
   ) ;                                                                                                                                                                                                           


